def test_broken_pipe():
    r, w = os.pipe()
    os.close(r)

    # Open the write end as a text file
    with os.fdopen(w, 'w') as f:
        console = Console(file=f)
        try:
            # Print enough to overflow the buffer or just enough to trigger a write
            for i in range(100):
